bool fullVoiceFixture(const File& file){
    file.getParentDirectory().createDirectory();TemporaryFile temporary(file);std::unique_ptr<OutputStream> stream(temporary.getFile().createOutputStream());WavAudioFormat format;auto writer=stream?format.createWriterFor(stream,AudioFormatWriterOptions{}.withSampleRate(8000).withNumChannels(1).withBitsPerSample(24)):nullptr;if(!writer)return false;AudioBuffer<float> block(1,4096);
    for(int pos=0;pos<8000*420;pos+=4096){int n=jmin(4096,8000*420-pos);for(int i=0;i<n;++i)block.setSample(0,i,pos+i>8000*240?.31f:.05f);if(!writer->writeFromAudioSampleBuffer(block,0,n))return false;}writer.reset();stream.reset();return temporary.overwriteTargetFileWithTemporary();
}
